function json(body, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "content-type": "application/json; charset=utf-8" },
  });
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (request.method === "POST" && url.pathname === "/api/tools/remember") {
      let input;
      try {
        input = await request.json();
      } catch {
        return json({ error: "Invalid request." }, 400);
      }

      const note = String(input?.note ?? "").trim();
      if (!note) return json({ error: "note is required." }, 400);
      if (note.length > 2000) return json({ error: "note must be 2000 characters or fewer." }, 400);

      const createdAt = Date.now();
      const result = env.db.execute(
        "INSERT INTO notes (note, created_at) VALUES (?, ?) RETURNING id",
        [note, createdAt],
      );
      return json({ remembered: true, id: Number(result.rows[0]?.id ?? 0), note, created_at: createdAt }, 201);
    }

    return json({ error: "Not found." }, 404);
  },
};

{
  "tools": [
    {
      "name": "remember",
